import java.util.*;

public class Demo {
  static <T extends Comparable<T>> T max(List<? extends T> items) {
    T best = items.get(0);
    for (T t : items) if (t.compareTo(best) > 0) best = t;
    return best;
  }

  public static void main(String[] args) {
    System.out.println(max(List.of(3, 7, 2, 9, 4)));
  }
}

